/* M4: eigene Erklärungen zu Subjektpronomen und être. */
(()=>{const lessons=[{"id": "m4-l1", "icon": "01", "title": "Das Subjekt finden", "subtitle": "Erst klären, über wen oder was der Satz etwas sagt.", "minutes": "12–18", "goals": ["das ganze Subjekt in einfachen Sätzen finden", "Sprecher und benannte Person unterscheiden"], "scene": {"intro": "Lies die Situation und die Bedeutungshilfen. Achte auf die markante Veränderung zwischen den Sätzen.", "lines": [["Nora", "Lina est à Paris.", "Lina ist in Paris."], ["Nora", "Lina et Samir sont à Paris.", "Lina und Samir sind in Paris."]], "caption": "Im ersten Satz ist Lina das Subjekt. Im zweiten gehören Lina und Samir gemeinsam dazu."}, "discover": {"type": "choice", "prompt": "Wer ist laut „Lina et Samir sont à Paris“ in Paris?", "options": ["Nur Lina", "Lina und Samir", "Paris"], "answer": 1, "why": "Beide Namen gehören hier zum gemeinsamen Subjekt.", "support": "et = und; sont à Paris = sind in Paris", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-d"}, "explain": [["Über wen sagt der Satz etwas?", "<p>Ein einfacher Satz sagt etwas über jemanden oder etwas. In <span lang=\"fr\">Lina est à Paris.</span> wird über Lina gesagt, dass sie in Paris ist. Der Satzteil <b>Lina</b> heißt hier <b>Subjekt</b>. Du findest ihn mit der Frage: Wer oder was ist hier in Paris? Das Wort est ist das Verb, eine Form von être (sein).</p><p>Das Subjekt muss kein einzelnes Wort sein. In <span lang=\"fr\">Les filles sont à Paris.</span> ist die ganze Gruppe les filles das Subjekt. Les ist der Begleiter, filles das Nomen. Zusammen beantworten sie die Frage, über wen etwas gesagt wird.</p>"], ["Die ganze Gruppe betrachten", "<p>In <span lang=\"fr\">Lina et Samir sont à Paris.</span> verbindet et zwei verschiedene Personen. Zusammen bilden sie das Subjekt. Nur den ersten Namen zu betrachten, wäre hier zu wenig. Für die spätere Verbwahl zählt die ganze gemeinte Gruppe.</p><p>Zwei Namen irgendwo im Satz bedeuten aber nicht automatisch ein gemeinsames Subjekt. In <span lang=\"fr\">Lina est avec Samir.</span> – Lina ist mit Samir zusammen – lautet das Subjekt nur Lina. Auf Wer ist mit Samir zusammen? antwortest du Lina. Avec Samir ist eine zusätzliche Angabe.</p>"], ["Gesprächsrollen nicht vermischen", "<p>Die Person, die spricht, ist der <b>Sprecher</b>. Die Person, die direkt angesprochen wird, ist das <b>Gegenüber</b>. Daneben kann über eine andere Person gesprochen werden. Wenn Nora zu Samir sagt „Lina ist in Paris“, spricht Nora; das Subjekt des gesprochenen Satzes ist aber Lina.</p><p>Beim späteren Ersetzen durch ein Pronomen brauchst du die Rolle: Gehört der Sprecher zum gemeinten Subjekt? Wird jemand direkt angesprochen oder wird über jemanden gesprochen? Bloßes Abzählen reicht deshalb nicht für alle Pronomen.</p>"], ["Eine verlässliche Arbeitsreihenfolge", "<p>Lies den ganzen Satz und die Bedeutungshilfe. Frage, über wen oder was die Aussage gemacht wird. Markiere das ganze Subjekt. Erst dann wählst du ein Pronomen und die dazugehörige Verbform. Der Lernweg heißt <b>Subjekt → Pronomen → Verb</b>.</p><p>Du brauchst dafür keine neuen Ortswörter auswendig zu lernen. À Paris bedeutet hier in Paris, ensemble zusammen. Solche Hilfen stehen bei den Aufgaben. Heute wird das Subjekt in einfachen Sätzen geübt, noch kein vollständiger Satzgliedkurs.</p>"]], "worked": {"task": "Finde das ganze Subjekt: Nora et Inès sont ensemble.", "steps": [["1 · Bedeutung", "Nora und Inès sind zusammen."], ["2 · Frage", "Wer ist zusammen? Nora und Inès."], ["3 · Gruppe", "Et verbindet die zwei verschiedenen Personen."], ["4 · Weiterdenken", "Nora et Inès → später Pronomen → Verbform."]], "trap": "Nicht nur das erste Wort unterstreichen. Nicht alle Namen im Satz gehören automatisch zum Subjekt."}, "sound": {"text": "Lina est à Paris. Lina et Samir sont à Paris.", "note": "Optional anhören und mitlesen. Die Systemstimme ist keine Aussprachebewertung."}, "practice": [{"type": "choice", "prompt": "Was ist das ganze Subjekt in „Les filles sont ensemble“?", "options": ["Les filles", "sont", "ensemble"], "answer": 0, "why": "Begleiter und Nomen bilden die ganze Subjektgruppe.", "support": "les filles = die Mädchen; sont ensemble = sind zusammen", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-p1"}, {"type": "choice", "prompt": "Nora sagt zu Samir: „Lina est à Paris.“ Wer spricht, und über wen wird gesprochen?", "options": ["Lina spricht über Nora.", "Nora spricht über Lina.", "Samir spricht über Paris."], "answer": 1, "why": "Nora ist die Sprecherin. Lina ist das Subjekt des gesprochenen Satzes.", "support": "Lina est à Paris = Lina ist in Paris", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-p2"}, {"type": "choice", "prompt": "Was ist das Subjekt in „Lina est avec Samir“?", "options": ["Lina", "Lina und Samir", "Samir"], "answer": 0, "why": "Über Lina wird gesagt, dass sie mit Samir zusammen ist.", "support": "Lina est avec Samir = Lina ist mit Samir zusammen", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-p3"}], "transfer": {"type": "choice", "prompt": "Neuer Satz: „Le musée est à Paris.“ Was ist das ganze Subjekt?", "options": ["Paris", "est", "Le musée"], "answer": 2, "why": "Über das Museum wird eine Ortsangabe gemacht.", "support": "le musée = das Museum; est à Paris = ist in Paris", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-t"}, "check": [{"type": "choice", "prompt": "Welches Subjekt nennt mehrere verschiedene Personen: „Noé et Amir sont ensemble“?", "options": ["Noé et Amir", "Noé allein", "Amir allein"], "answer": 0, "why": "Et verbindet die beiden Personen zum gemeinsamen Subjekt.", "support": "et = und; sont ensemble = sind zusammen", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-c1"}, {"type": "choice", "prompt": "Welche Reihenfolge hilft beim Lösen?", "options": ["Zufällig eine Verbform wählen.", "Das ganze Subjekt und die Rolle klären, dann Pronomen und Verb verbinden.", "Nur den ersten Artikel übersetzen."], "answer": 1, "why": "Erst Bezug und Rolle, dann Pronomen und Verb.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l1-c2"}], "card": {"rule": "Finde das ganze Subjekt und seine Gesprächsrolle, bevor du Pronomen und Verbform wählst.", "example": "Nora et Inès sont ensemble. → Subjekt: Nora et Inès", "trap": "Nicht nur das erste Wort unterstreichen. Nicht alle Namen im Satz gehören automatisch zum Subjekt."}}, {"id": "m4-l2", "icon": "02", "title": "Il und elle ersetzen ein Nomen", "subtitle": "Über eine Person oder Sache sprechen, ohne den Namen ständig zu wiederholen.", "minutes": "12–18", "goals": ["il und elle auf eine einzelne dritte Person oder Sache beziehen", "französisches Genus beim Ersetzen nutzen"], "scene": {"intro": "Lies die Situation und die Bedeutungshilfen. Achte auf die markante Veränderung zwischen den Sätzen.", "lines": [["Nora", "Lina est à Paris. Elle est dans le parc.", "Lina ist in Paris. Sie ist im Park."], ["Samir", "Le musée est à Paris. Il est dans le quartier.", "Das Museum ist in Paris. Es ist im Viertel."]], "caption": "Il kann ein französisch männliches Nomen für eine Sache ersetzen. Die deutsche Übersetzung ist dann nicht unbedingt er."}, "discover": {"type": "choice", "prompt": "Wofür steht il im Museumsbeispiel?", "options": ["Für das Museum", "Für die Sprecherin", "Für mehrere Personen"], "answer": 0, "why": "Il ersetzt le musée, ein maskulines Nomen im Singular.", "support": "musée = Museum · masculin · Singular", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l2-d"}, "explain": [["Ein Pronomen übernimmt den Bezug", "<p>Statt immer Lina zu sagen, kannst du im passenden Zusammenhang <span lang=\"fr\">elle</span> verwenden: <span lang=\"fr\">Elle est à Paris.</span> Das Pronomen steht jetzt als Subjekt. Der Leser muss erkennen können, dass elle Lina meint. Ein Pronomen ohne klaren Bezug hilft nicht weiter.</p><p>Hier wird <b>über</b> die Person gesprochen. Sie ist nicht automatisch die Sprecherin und wird auch nicht direkt mit du angesprochen. Darum brauchst du in diesem Satz nicht je oder tu.</p>"], ["Die Rollenkarte nennt die Person", "<p>Für einen einzelnen Jungen oder Mann verwenden wir in den angegebenen Rollen <b>il</b>, für ein einzelnes Mädchen oder eine Frau <b>elle</b>. Die Rollenkarte nennt die Person genauer. Du musst das nicht aus einem unbekannten Vornamen erraten.</p><p>Bei être gehören dieselben Formen dazu: <span lang=\"fr\">il est</span> und <span lang=\"fr\">elle est</span>. Das Pronomen ändert sich, aber est bleibt. Es kommt keine zusätzliche weibliche Endung an diese Verbform.</p>"], ["Auch Sachen haben französisches Genus", "<p>Il und elle können hier auch Nomengruppen für Sachen ersetzen. Nutze das <b>französische Genus</b>: <span lang=\"fr\">le musée → il</span>, <span lang=\"fr\">la tour → elle</span>. Ein Museum ist keine männliche Person. Die Pronomen folgen der grammatischen Einteilung des französischen Nomens.</p><p>Das deutsche „es“ kann in die Irre führen. Le musée heißt „das Museum“, wird hier aber durch il ersetzt. La tour heißt „der Turm“, wird hier durch elle ersetzt. Die nötigen französischen Angaben stehen deshalb sichtbar bei der Aufgabe.</p>"], ["Ersetzen und Benennen unterscheiden", "<p><span lang=\"fr\">C’est Lina.</span> benennt in der bekannten Vorstellungsaufgabe eine Person. <span lang=\"fr\">Elle est à Paris.</span> macht anschließend eine Aussage über Lina. Nicht jede Aussage über ein Mädchen beginnt also mit c’est. Die Muster haben unterschiedliche Aufgaben.</p><p>Zum Ersetzen prüfst du: Ist der Bezug klar? Wird über eine einzelne Person oder Sache gesprochen? Welche Rollen- oder Genusangabe steht dabei? Danach verbindest du il oder elle mit est. Eine vollständige Gegenüberstellung aller c’est-/il-est-Konstruktionen ist hier nicht nötig.</p>"]], "worked": {"task": "Ersetze das Subjekt: La tour est à Paris.", "steps": [["1 · Bezug", "Das Subjekt ist la tour, der Turm."], ["2 · Wortangaben", "Tour ist féminin und Singular."], ["3 · Pronomen", "La tour → elle."], ["4 · Paar", "Elle est à Paris."]], "trap": "Die deutsche Form der Turm führt nicht zu il. Verwende das französische Genus aus der Wortkarte."}, "sound": {"text": "Il est à Paris. Elle est à Paris.", "note": "Optional anhören und mitlesen. Die Systemstimme ist keine Aussprachebewertung."}, "practice": [{"type": "slots", "prompt": "Über Noé wird gesprochen, laut Rolle ein einzelner Junge. Ersetze den Namen und ergänze être.", "slots": [{"label": "Pronomen", "options": ["je", "il", "elle"], "answer": 1, "feedback": "Es wird über einen einzelnen Jungen gesprochen, nicht über den Sprecher."}, {"label": "Verb", "options": ["suis", "est", "sont"], "answer": 1, "feedback": "Verb und Subjektpronomen müssen zusammenpassen; prüfe die Singularform bei il."}], "why": "Il est: ein einzelner Junge, über den gesprochen wird.", "support": "gemeint: Er ist in Paris; à Paris = in Paris", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l2-p1"}, {"type": "short", "prompt": "Ersetze nur das Subjekt: ___ est à Paris. Gemeint ist Lina, laut Rolle ein einzelnes Mädchen.", "answers": ["Elle"], "why": "Über ein einzelnes Mädchen wird hier mit elle gesprochen.", "support": "est à Paris = ist in Paris", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l2-p2"}, {"type": "slots", "prompt": "Ersetze le musée als Subjekt und ergänze die passende Verbform.", "slots": [{"label": "Pronomen", "options": ["il", "elle", "ils"], "answer": 0, "feedback": "Musée ist französisch masculin und Singular. Nicht vom deutschen das ableiten."}, {"label": "Verb", "options": ["sont", "est", "sommes"], "answer": 1, "feedback": "Ein einzelnes als il aufgenommenes Nomen braucht die Singularform."}], "why": "Le musée → il → est.", "support": "musée = Museum · masculin · Singular; à Paris = in Paris", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l2-p3"}], "transfer": {"type": "slots", "prompt": "Neue Wortkarte: la rue. Ersetze die Subjektgruppe der Ortsaussage.", "slots": [{"label": "Pronomen", "options": ["il", "elle", "elles"], "answer": 1, "feedback": "Rue ist féminin und Singular. Es wird über eine Straße gesprochen."}, {"label": "Verb", "options": ["est", "sont", "êtes"], "answer": 0, "feedback": "Die Verbform muss zum gewählten Pronomen passen."}], "why": "La rue → elle → est.", "support": "rue = Straße · féminin · Singular; à Paris = in Paris", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l2-t"}, "check": [{"type": "choice", "prompt": "Welches Pronomen ersetzt la tour als Subjekt einer Aussage über diesen einen Turm?", "options": ["il", "elle", "elles"], "answer": 1, "why": "Tour ist französisch féminin und Singular: elle.", "support": "tour = Turm · féminin · Singular", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l2-c1"}, {"type": "short", "prompt": "Ergänze nur être: Il ___ dans le parc.", "answers": ["est"], "why": "Zu il gehört est.", "support": "dans le parc = im Park", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l2-c2"}], "card": {"rule": "Über eine einzelne Person oder Sache: il/elle nach Rollen- oder Genusangabe. Bei être: il est, elle est.", "example": "le musée → il est · la tour → elle est", "trap": "Die deutsche Form der Turm führt nicht zu il. Verwende das französische Genus aus der Wortkarte."}}];const D=globalThis.FRENCH_COURSE;D.lessons.push(...lessons);Object.assign(D.modules.find(m=>m.id==="m4"),{available:true,subtitle:"Vom Subjekt zum Pronomen zur passenden Verbform"});})();

/* Weitere Lektionen und Prüfungen, stabile Kennungen. */
(()=>{const data={"lessons": [{"id": "m4-l3", "icon": "03", "title": "Être: ein Verb, mehrere Formen", "subtitle": "Die Gegenwartsformen von sein als zusammengehörige Paare lernen.", "minutes": "12–18", "goals": ["alle Präsensformen von être einem Subjektpronomen zuordnen", "unregelmäßige Formen und die Schreibung von êtes beachten"], "scene": {"intro": "Lies die Situation und die Bedeutungshilfen. Achte auf die markante Veränderung zwischen den Sätzen.", "lines": [["Nora", "Je suis à Paris. Tu es à Paris.", "Ich bin in Paris. Du bist in Paris."], ["Samir", "Nous sommes ensemble. Vous êtes ensemble.", "Wir sind zusammen. Ihr seid zusammen."]], "caption": "Être heißt sein. Die Form im Satz hängt vom Subjekt ab; die Ortsangabe verändert sie nicht."}, "discover": {"type": "choice", "prompt": "Welches vollständige Paar ist richtig?", "options": ["je sommes", "je suis", "je êtes"], "answer": 1, "why": "Das Paar lautet je suis.", "support": "je = ich; être = sein", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l3-d"}, "explain": [["Grundform und Satzform", "<p><b>Être</b> ist die Grundform des Verbs: sein. Im Satz sagst du aber nicht „je être“, genauso wenig wie auf Deutsch „ich sein“. Du brauchst eine zur Person passende Gegenwartsform. Diese Veränderung des Verbs heißt <b>konjugieren</b>. Das Pronomen und die Verbform bilden ein Paar.</p><p>Être ist unregelmäßig. Für dieses Verb hilft keine erfundene Regel wie „immer den gleichen Stamm nehmen und s anhängen“. Lerne die kurzen Paare und verbinde sie mit Situationen. Die Tabelle in der Werkstatt zeigt alle Formen nebeneinander.</p>"], ["Die vollständigen Paare", "<p><span lang=\"fr\"><b>je suis</b>, <b>tu es</b>, <b>il est / elle est / on est</b>, <b>nous sommes</b>, <b>vous êtes</b>, <b>ils sont / elles sont</b></span>. Bei il, elle und on ist die Verbform gleich. Auch ils und elles teilen sich eine Form.</p><p>Singular bedeutet hier grammatische Einzahl, Plural Mehrzahl. On steht grammatisch in der Einzahl, auch wenn es im Gespräch wir bedeuten kann. Vous kann eine Gruppe ansprechen oder höflich eine einzelne Person. Diese Fälle werden in einer eigenen Lektion genauer erklärt.</p>"], ["Die Ergänzung ist nicht der Entscheider", "<p><span lang=\"fr\">Je suis à Paris.</span> heißt „Ich bin in Paris.“ <span lang=\"fr\">Je suis dans le parc.</span> heißt „Ich bin im Park.“ Der Ort wechselt, aber je bleibt das Subjekt. Deshalb bleibt suis. In <span lang=\"fr\">Nous sommes à Paris.</span> wechselt dagegen das Subjekt; nun brauchst du sommes.</p><p>Prüfe beim Ergänzen einer Lücke zuerst das Subjekt und nicht das nächste bekannte Ortswort. Die Bedeutung aller Ergänzungen steht neben der Aufgabe.</p>"], ["Schriftbild sorgfältig mitlernen", "<p><span lang=\"fr\">Tu es</span> und <span lang=\"fr\">il est</span> sind verschieden geschrieben, auch wenn du beim Hören einen ähnlichen Klang wahrnimmst. Das t in est wird hier nicht einfach als deutsches t gesprochen. Die passende Schreibweise erkennst du am Subjekt.</p><p>Bei <b>êtes</b> gehört der accent circonflexe dazu. Nutze bei Bedarf die Akzentleiste. Eine Antwort ohne Akzent wird bei den begrenzten Schreibaufgaben nicht als dieselbe französische Form behandelt. Lies anschließend das ganze Paar statt nur die isolierte Lücke.</p>"]], "worked": {"task": "Ergänze: Vous ___ dans le parc.", "steps": [["1 · Subjekt", "Das Subjekt ist vous."], ["2 · Verb bestimmen", "Gesucht ist eine Gegenwartsform von être, sein."], ["3 · Paar nachsehen", "In der Tabelle steht vous êtes."], ["4 · Ganzen Satz lesen", "Vous êtes dans le parc. = Ihr seid / Sie sind im Park."]], "trap": "Nicht vom deutschen bin/bist auf französische Endungen schließen. Être hat unregelmäßige Formen; êtes braucht seinen Akzent."}, "sound": {"text": "Je suis. Tu es. Elle est. On est. Nous sommes. Vous êtes. Ils sont.", "note": "Optional anhören und mitlesen. Die Systemstimme ist keine Aussprachebewertung."}, "practice": [{"type": "short", "prompt": "Ergänze nur das Verb: Tu ___ à Paris.", "answers": ["es"], "why": "Tu es: Zum du gehört es.", "support": "à Paris = in Paris", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [{"includes": "est", "message": "Du hast die Form für il/elle/on gewählt. Prüfe das Paar mit tu und seine Schreibung."}], "id": "m4-l3-p1"}, {"type": "short", "prompt": "Ergänze: Nous ___ ensemble.", "answers": ["sommes"], "why": "Zu nous gehört sommes.", "support": "nous = wir; ensemble = zusammen", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l3-p2"}, {"type": "slots", "prompt": "Setze die beiden unabhängig voneinander passenden Verbformen ein.", "slots": [{"label": "elle …", "options": ["est", "es", "sont"], "answer": 0, "feedback": "Elle ist dritte Person Singular. Prüfe das Paar elle est."}, {"label": "ils …", "options": ["sommes", "est", "sont"], "answer": 2, "feedback": "Ils ist dritte Person Plural. Prüfe das Paar ils sont."}], "why": "Elle est und ils sont sind verschiedene Paare.", "support": "elle = sie, eine Person; ils = sie, mehrere Personen", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l3-p3"}], "transfer": {"type": "short", "prompt": "Neue Ergänzung, dieselbe Regel: Vous ___ en retard.", "answers": ["êtes"], "why": "Vous bleibt das Subjekt. Darum vous êtes, unabhängig von en retard.", "support": "en retard = verspätet; vous = ihr oder höfliches Sie", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l3-t"}, "check": [{"type": "short", "prompt": "Ergänze: Je ___ dans la classe.", "answers": ["suis"], "why": "Je suis ist das richtige Paar.", "support": "dans la classe = in der Klasse", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l3-c1"}, {"type": "choice", "prompt": "Welche Form gehört sowohl zu il als auch zu elle und on?", "options": ["sont", "es", "est"], "answer": 2, "why": "Il est, elle est und on est haben dieselbe Verbform.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l3-c2"}], "card": {"rule": "Être ist unregelmäßig. Verbinde jedes Subjektpronomen mit seiner festen Präsensform.", "example": "je suis · tu es · il/elle/on est · nous sommes · vous êtes · ils/elles sont", "trap": "Nicht vom deutschen bin/bist auf französische Endungen schließen. Être hat unregelmäßige Formen; êtes braucht seinen Akzent."}, "workshop": true}, {"id": "m4-l4", "icon": "04", "title": "Nous, ils oder elles?", "subtitle": "Die ganze Gruppe und den Platz der sprechenden Person beachten.", "minutes": "12–18", "goals": ["nous von einer Gruppe unterscheiden, über die gesprochen wird", "ils und elles anhand ausdrücklich genannter Gruppenrollen wählen"], "scene": {"intro": "Lies die Situation und die Bedeutungshilfen. Achte auf die markante Veränderung zwischen den Sätzen.", "lines": [["Nora", "Inès et moi, nous sommes à Paris.", "Inès und ich, wir sind in Paris."], ["Nora", "Inès et Lina, elles sont à Paris.", "Inès und Lina, sie sind in Paris."]], "caption": "In beiden Fällen sind es zwei Personen. Entscheidend ist zusätzlich, ob die Sprecherin zur gemeinten Gruppe gehört."}, "discover": {"type": "choice", "prompt": "Nora spricht über sich und Inès. Welches Pronomen meint ihre eigene Gruppe?", "options": ["elles", "nous", "vous"], "answer": 1, "why": "Die Sprecherin gehört dazu: nous.", "support": "Inès ist laut Rolle ein Mädchen.", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l4-d"}, "explain": [["Wir schließt die sprechende Person ein", "<p><b>Nous</b> bedeutet wir. Die Person, die gerade spricht, gehört selbst zur gemeinten Gruppe. Nora kann über sich und Inès sagen: <span lang=\"fr\">Nous sommes à Paris.</span> Die Gruppe kann aus zwei oder mehr Personen bestehen.</p><p>Wenn Nora dagegen über Inès und Lina spricht und selbst nicht zu dieser Gruppe gehört, passt nous nicht. Prüfe deshalb vor der Anzahl die Perspektive: Spricht jemand über die eigene Gruppe oder über eine andere?</p>"], ["Über mehrere Personen sprechen", "<p>Für eine Gruppe, über die gesprochen wird, stehen hier <b>ils</b> oder <b>elles</b>. Nach der in diesem Kurs geübten Standardregel steht elles für eine Gruppe nur aus Mädchen/Frauen. Ils steht für eine Gruppe nur aus Jungen/Männern oder eine ausdrücklich gemischte Gruppe.</p><p>Die Rollen der Figuren werden in den Aufgaben genannt. Ein Name allein soll keine versteckte Information über die Gruppe liefern. In beiden Fällen ist die Verbform <b>sont</b>: ils sont, elles sont.</p>"], ["Nicht nur die letzte Person betrachten", "<p>Bei „Nora et Samir“ gehören beide verschiedenen Personen zum gemeinsamen Subjekt. Ist Nora laut Rolle ein Mädchen und Samir ein Junge, ist es die hier angegebene gemischte Gruppe: ils. Es spielt dafür keine Rolle, welcher Name zuletzt steht.</p><p>Wenn Samir selbst über sich und Nora spricht, ist die Perspektive neu: Er gehört zur Gruppe, also nous sommes. Dieselben Personen können je nach Gesprächsrolle mit einem anderen Pronomen bezeichnet werden.</p>"], ["Auch bei Sachen auf französische Angaben achten", "<p>Bei Sachgruppen richtet sich der Bezug nach dem französischen Genus. <span lang=\"fr\">Les tours</span> ist eine hier feminine Pluralgruppe, also elles; <span lang=\"fr\">les musées</span> eine maskuline Pluralgruppe, also ils. Die deutschen Übersetzungen entscheiden nicht darüber.</p><p>Für deine Lösung notierst du gedanklich drei Angaben: Gehört die sprechende Person dazu? Welche Gruppe ist gemeint? Welches Pronomen-Verb-Paar passt? Damit löst du auch Aufgaben mit einer neuen bereitgestellten Wortkarte.</p>"]], "worked": {"task": "Nora spricht über sich und Samir: Beide sind im Park. Wähle das Paar.", "steps": [["1 · Sprecherin", "Nora sagt den Satz."], ["2 · Gruppe", "Nora und Samir sind gemeint. Nora gehört selbst dazu."], ["3 · Pronomen", "Eigene Gruppe → nous. Die Mischung der Gruppe ändert das nicht."], ["4 · Verb", "Nous sommes dans le parc."]], "trap": "Eine gemischte Gruppe führt nur dann zu ils, wenn über sie gesprochen wird. Gehört das ich zur Gruppe, verwende hier nous."}, "sound": {"text": "Nous sommes ensemble. Ils sont ensemble. Elles sont ensemble.", "note": "Optional anhören und mitlesen. Die Systemstimme ist keine Aussprachebewertung."}, "practice": [{"type": "slots", "prompt": "Nora spricht über Lina und Inès, zwei Mädchen; Nora selbst gehört nicht zu dieser Gruppe.", "slots": [{"label": "Pronomen", "options": ["nous", "elles", "ils"], "answer": 1, "feedback": "Es geht um zwei Mädchen, über die gesprochen wird; die Sprecherin gehört nicht dazu."}, {"label": "Verb", "options": ["est", "sont", "sommes"], "answer": 1, "feedback": "Zu diesem Pluralpronomen gehört sont."}], "why": "Elles sont: Gruppe nur aus Mädchen, über die Nora spricht.", "support": "gemeint: Sie sind in Paris.", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l4-p1"}, {"type": "choice", "prompt": "Nora spricht über Samir (Junge) und Lina (Mädchen). Beide sind gemeint.", "options": ["elle est", "elles sont", "ils sont"], "answer": 2, "why": "Für die hier ausdrücklich gemischte Gruppe gilt ils sont.", "support": "Beide sind in Paris; Nora gehört nicht zur Gruppe.", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l4-p2"}, {"type": "short", "prompt": "Nora sagt für sich und Lina: ___ sommes dans le parc. Ergänze nur das Pronomen.", "answers": ["Nous"], "why": "Zur eigenen Gruppe gehört die Sprecherin: nous.", "support": "dans le parc = im Park", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l4-p3"}], "transfer": {"type": "slots", "prompt": "Neue Wortkarte: les tours, mehrere Türme. Ersetze die ganze Sachgruppe.", "slots": [{"label": "Pronomen", "options": ["elles", "il", "ils"], "answer": 0, "feedback": "Tour ist im Französischen féminin; die Gruppe steht im Plural."}, {"label": "Verb", "options": ["est", "sommes", "sont"], "answer": 2, "feedback": "Das gewählte Pronomen steht in der dritten Person Plural."}], "why": "Les tours → elles sont.", "support": "tour = Turm · féminin; les tours = die Türme · Plural; à Paris = in Paris", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l4-t"}, "check": [{"type": "choice", "prompt": "Samir sagt über sich und zwei Freunde: „Wir sind zusammen.“ Welches Paar braucht er?", "options": ["ils sont", "nous sommes", "vous êtes"], "answer": 1, "why": "Samir spricht über seine eigene Gruppe: nous sommes.", "support": "ensemble = zusammen", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l4-c1"}, {"type": "short", "prompt": "Lina und Inès sind zwei Mädchen. Nora spricht über beide: Elles ___ à Paris.", "answers": ["sont"], "why": "Elles sont: dritte Person Plural.", "support": "à Paris = in Paris", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l4-c2"}], "card": {"rule": "Eigene Gruppe: nous sommes. Über andere Gruppen: elles sont (nur weiblich) oder ils sont (männlich/gemischt nach Rollenangabe).", "example": "Nora über sich + Inès: nous sommes. Nora über Lina + Inès: elles sont.", "trap": "Eine gemischte Gruppe führt nur dann zu ils, wenn über sie gesprochen wird. Gehört das ich zur Gruppe, verwende hier nous."}, "workshop": true}, {"id": "m4-l5", "icon": "05", "title": "On und vous: genauer hinschauen", "subtitle": "Warum die Zahl der gemeinten Menschen nicht immer die Verbform verrät.", "minutes": "12–18", "goals": ["on est von nous sommes unterscheiden", "Mehrzahl-vous und höfliches vous mit êtes verbinden"], "scene": {"intro": "Lies die Situation und die Bedeutungshilfen. Achte auf die markante Veränderung zwischen den Sätzen.", "lines": [["Nora", "On est dans le parc.", "Wir sind im Park. (Hier meint on unsere Gruppe.)"], ["Samir zu einer Lehrerin", "Vous êtes à Paris ?", "Sind Sie in Paris?"]], "caption": "On kann hier mehrere Menschen meinen und hat trotzdem est. Höfliches vous kann eine einzelne Person meinen und hat trotzdem êtes."}, "discover": {"type": "choice", "prompt": "On bedeutet hier wir. Welche Form ist trotzdem richtig?", "options": ["on sommes", "on sont", "on est"], "answer": 2, "why": "On hat grammatisch die dritte Person Singular: on est.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l5-d"}, "explain": [["On: Bedeutung und Grammatik unterscheiden", "<p>Im vertrauten Gespräch verwendet man häufig <b>on</b> für wir. Nora und Samir können über ihre Gruppe sagen: <span lang=\"fr\">On est ensemble.</span> Das meint hier „Wir sind zusammen.“ Grammatisch gehört on trotzdem zur <b>dritten Person Singular</b>. Deshalb bleibt die Verbform <b>est</b>.</p><p>Du kannst dieselbe Gruppenidee mit <span lang=\"fr\">Nous sommes ensemble.</span> ausdrücken. Beim Wechsel des Pronomens muss auch die Verbform wechseln. Die Verbindung „on sommes“ mischt zwei verschiedene Paare und passt nicht.</p>"], ["On kann auch unbestimmt sein", "<p>On kann je nach Zusammenhang auch man bedeuten, also Menschen allgemein oder jemanden, den man nicht genauer nennt. Du musst seine Bedeutung aus der Situation erschließen. In unseren Aufgaben steht ausdrücklich dabei, ob eine eigene Gruppe oder ein allgemeines man gemeint ist.</p><p>Die Verbregel bleibt in beiden Fällen dieselbe: on est. Verwechsle daher nicht „Es sind mehrere Menschen gemeint“ mit „Das Subjekt ist grammatisch Plural“. Die Aufgabe fragt nach der französischen Form, nicht nur nach einer Kopfzahl.</p>"], ["Vous: Gruppe oder höfliche Einzelperson", "<p><b>Vous</b> kann eine Gruppe direkt ansprechen: „ihr“. Nora fragt zwei Kinder <span lang=\"fr\">Vous êtes dans le parc ?</span> Es wird mit den Kindern gesprochen, nicht über sie. Deshalb steht vous und nicht ils oder elles.</p><p>Vous ist außerdem die höfliche Anrede einer einzelnen Person: „Sie“. Spricht Samir seine Lehrerin höflich an, bleibt es <span lang=\"fr\">vous êtes</span>. Die Form ändert sich nicht zu est, nur weil gerade eine einzelne Erwachsene angesprochen wird.</p>"], ["Eine kleine Kontrollroutine", "<p>Frage zuerst: Welches Pronomen steht wirklich im französischen Satz? On führt zu est, nous zu sommes, vous zu êtes. Erst danach prüfst du, was das Pronomen in der Situation bedeutet. So vermischst du Bedeutung und Form nicht.</p><p>Beim Antworten kann die Perspektive wechseln: Eine höflich mit vous angesprochene Person antwortet über sich mit je suis. Eine angesprochene Gruppe kann mit nous sommes antworten. In M5 werden diese Wechsel zu einem vollständigen Antwortweg verbunden.</p>"]], "worked": {"task": "Repariere „On sommes à Paris“, wenn on hier wir bedeutet.", "steps": [["1 · Gemeinte Gruppe", "On meint hier die Sprechergruppe."], ["2 · Tatsächliches Subjekt", "Im französischen Satz steht on, nicht nous."], ["3 · Festes Paar", "Zu on gehört est, auch bei der Bedeutung wir."], ["4 · Korrigierte Fassung", "On est à Paris. Alternativ mit Pronomenwechsel: Nous sommes à Paris."]], "trap": "Nicht nur Personen zählen: on est und höfliches vous êtes bleiben ihre festen grammatischen Paare."}, "sound": {"text": "On est ensemble. Nous sommes ensemble. Vous êtes à Paris.", "note": "Optional anhören und mitlesen. Die Systemstimme ist keine Aussprachebewertung."}, "practice": [{"type": "short", "prompt": "Ergänze nur être: On ___ ensemble.", "answers": ["est"], "why": "On est gilt auch dann, wenn on unsere Gruppe meint.", "support": "ensemble = zusammen; on bedeutet hier wir", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [{"includes": "sommes", "message": "Du hast die Form von nous gewählt. Im Satz steht aber on; es braucht die dritte Person Singular."}, {"includes": "sont", "message": "Die gemeinte Gruppe ist nicht das Entscheidende. Das tatsächlich verwendete Pronomen on bleibt grammatisch Singular."}], "id": "m4-l5-p1"}, {"type": "slots", "prompt": "Samir spricht genau eine Lehrerin höflich an.", "slots": [{"label": "Pronomen", "options": ["tu", "vous", "elle"], "answer": 1, "feedback": "Die Rollenkarte verlangt die höfliche direkte Anrede einer einzelnen Person."}, {"label": "Verb", "options": ["est", "es", "êtes"], "answer": 2, "feedback": "Höfliches vous hat dieselbe Verbform wie Mehrzahl-vous."}], "why": "Vous êtes: höfliche Anrede, auch bei einer einzelnen Lehrerin.", "support": "gemeint: Sie sind in Paris.", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l5-p2"}, {"type": "choice", "prompt": "Nora spricht direkt zu drei Kindern. Welches Paar passt für ihr seid?", "options": ["ils sont", "vous êtes", "nous sommes"], "answer": 1, "why": "Direkte Anrede einer Gruppe: vous êtes.", "support": "à Paris = in Paris", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l5-p3"}], "transfer": {"type": "short", "prompt": "Ersetze on durch nous und passe das Verb an. Schreibe den ganzen Satz: On est ensemble.", "answers": ["Nous sommes ensemble.", "Nous sommes ensemble"], "why": "On est und nous sommes können hier dieselbe eigene Gruppe meinen. Beim Pronomenwechsel ändert sich die Form.", "support": "ensemble = zusammen; on bedeutet hier wir", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l5-t"}, "check": [{"type": "short", "prompt": "Höfliche Anrede einer einzelnen Person: Vous ___ dans le parc.", "answers": ["êtes"], "why": "Auch höfliches vous verlangt êtes.", "support": "dans le parc = im Park", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l5-c1"}, {"type": "choice", "prompt": "Welche Begründung für on est stimmt?", "options": ["On braucht wegen seiner grammatischen Form die dritte Person Singular.", "On meint immer genau einen Mann.", "On ist immer Plural, aber ein Tippfehler bleibt erlaubt."], "answer": 0, "why": "On bleibt grammatisch dritte Person Singular; seine Bedeutung ergibt sich aus dem Kontext.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l5-c2"}], "card": {"rule": "On est: grammatisch Singular, auch bei wir. Vous êtes: direkte Gruppenanrede oder höfliche Einzelanrede.", "example": "On est ensemble. = hier: Wir sind zusammen. Vous êtes à Paris ? = Ihr seid / Sind Sie in Paris?", "trap": "Nicht nur Personen zählen: on est und höfliches vous êtes bleiben ihre festen grammatischen Paare."}, "workshop": true}, {"id": "m4-l6", "icon": "06", "title": "Den ganzen Weg selbst gehen", "subtitle": "Bezug, Pronomen und Verb verbinden und gezielt überarbeiten.", "minutes": "12–18", "goals": ["mehrteilige Pronomen-Verb-Aufgaben begründet lösen", "einen eigenen kurzen Text mit être prüfen"], "scene": {"intro": "Lies die Situation und die Bedeutungshilfen. Achte auf die markante Veränderung zwischen den Sätzen.", "lines": [["Nora", "Lina et Inès sont à Paris. Elles sont ensemble.", "Lina und Inès sind in Paris. Sie sind zusammen."], ["Samir", "On est dans le parc. Nous sommes ensemble.", "Wir sind im Park. Wir sind zusammen."]], "caption": "Der Bezug bleibt nachvollziehbar, auch wenn Namen durch Pronomen ersetzt werden oder on und nous wechseln."}, "discover": {"type": "choice", "prompt": "Was muss bei „Elles sommes ensemble“ geändert werden, wenn elles die richtige Gruppe meint?", "options": ["Nur sommes zu sont", "Elles immer zu nous", "Ensemble zu Paris"], "answer": 0, "why": "Der Bezug ist vorgegeben richtig. Die Verbform muss zu elles passen.", "support": "ensemble = zusammen", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l6-d"}, "explain": [["Die drei Schritte als Werkzeug", "<p>Beginne mit dem ganzen Subjekt und der Rollenangabe. Markiere, wer spricht, wer angesprochen wird und über wen gesprochen wird. Danach wählst du das Pronomen. Erst im dritten Schritt verbindest du dieses Pronomen mit seiner Form von être.</p><p>Die Werkstatt macht diesen Denkweg sichtbar. Sie analysiert keinen beliebigen selbst eingegebenen französischen Satz. Ihre vorgegebenen Situationen sind absichtlich eindeutig, damit du die Entscheidungen vergleichen kannst.</p>"], ["Zwei Fehlerarten getrennt prüfen", "<p>In einer Aufgabe mit zwei Auswahlfeldern kann das Pronomen falsch sein, während das Verb dazu zufällig richtig gewählt wurde. Umgekehrt kann der Bezug stimmen, aber die Verbform nicht. Prüfe deshalb die Felder nacheinander.</p><p>Bei <span lang=\"fr\">Elles sommes à Paris.</span> ist für die angegebene Mädchengruppe elles richtig, sommes aber nicht. Es muss elles sont heißen. Bei einer eigenen Sprechergruppe wäre dagegen nous sommes passend. Eine Korrektur muss zur konkreten Situation passen.</p>"], ["Ein klarer Bezug macht Texte verständlich", "<p>Wenn du mehrere Personen eingeführt hast, muss dein Leser erkennen können, auf wen il, elle, ils oder elles verweist. In einem kurzen Text hilft es, die gemeinte Gruppe zuerst zu nennen und anschließend mit dem passenden Pronomen fortzufahren.</p><p>Wird der Bezug unklar, wiederhole lieber den Namen oder die Nomengruppe. Das ist verständlicher, als ein Pronomen ohne erkennbare Bezugsgruppe einzusetzen. Die Schreibaufgabe gibt dir eine eindeutige Rolle und die benötigten Wörter.</p>"], ["Überarbeiten mit vier Prüffragen", "<p>Lies deinen fertigen Text einmal nur auf den Bezug hin: Wer ist in jedem Satz gemeint? Prüfe dann die Paare aus der Tabelle. Suche anschließend die Sonderfälle on und vous. Zuletzt kontrollierst du Schriftzeichen wie den Akzent in êtes.</p><p>Der freie Text bekommt keine erfundene automatische Sprachnote. Du siehst nach dem Vergleichen ein eigenes Beispiel und eine Checkliste. Geschlossene Mini-Checks prüfen dagegen genau die hinterlegten Lösungen und zeigen, wo Wiederholung hilft.</p>"]], "worked": {"task": "Nora spricht über zwei Mädchen: „Lina et Inès“. In der Fortsetzung steht „Elles sommes ensemble.“ Repariere.", "steps": [["1 · Bezug", "Elles meint die beiden genannten Mädchen. Nora gehört nicht zur Gruppe."], ["2 · Pronomen prüfen", "Elles passt zur Gruppe, über die gesprochen wird."], ["3 · Verb prüfen", "Sommes gehört zu nous. Zu elles gehört sont."], ["4 · Korrigiert lesen", "Elles sont ensemble. = Sie sind zusammen."]], "trap": "Nicht jede falsche Verbindung verlangt ein neues Pronomen. Prüfe erst den Bezug und dann die Verbform."}, "sound": {"text": "Je suis à Paris. Nous sommes ensemble. Elles sont dans le parc. On est en retard.", "note": "Optional anhören und mitlesen. Die Systemstimme ist keine Aussprachebewertung."}, "practice": [{"type": "slots", "prompt": "Samir spricht über sich und Nora. Wähle seine eigene Gruppe und die passende Form.", "slots": [{"label": "Pronomen", "options": ["ils", "nous", "vous"], "answer": 1, "feedback": "Samir als Sprecher gehört selbst zur gemeinten Gruppe."}, {"label": "Verb", "options": ["sont", "êtes", "sommes"], "answer": 2, "feedback": "Die Form muss zum Pronomen für die eigene Gruppe gehören."}], "why": "Die Perspektive ergibt nous, das Verb sommes.", "support": "Nora = Mädchen, Samir = Junge; gemeint: Wir sind in Paris.", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l6-p1"}, {"type": "short", "prompt": "Repariere den ganzen Satz, ohne vous zu ändern: Vous sommes à Paris.", "answers": ["Vous êtes à Paris.", "Vous êtes à Paris"], "why": "Vous verlangt êtes, unabhängig davon, ob ihr oder höfliches Sie gemeint ist.", "support": "à Paris = in Paris", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-l6-p2"}, {"type": "choice", "prompt": "Nora spricht über Lina. Samir wird nur als Begleitung genannt: „Lina est avec Samir.“ Welche Ersetzung bewahrt das Subjekt?", "options": ["Ils sont avec Samir.", "Elle est avec Samir.", "Nous sommes avec Samir."], "answer": 1, "why": "Das Subjekt ist nur Lina. Elle est ersetzt Lina est.", "support": "Lina = Mädchen; avec Samir = mit Samir", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l6-p3"}], "transfer": {"type": "open", "prompt": "Du spielst Nora. Schreibe vier Sätze: Du bist in Paris. Du und Samir seid zusammen. Lina und Inès (zwei Mädchen) sind im Park; ersetze die beiden Namen in diesem Satz durch ein Pronomen. Eure eigene Gruppe ist verspätet; verwende dafür on.", "support": "à Paris = in Paris; ensemble = zusammen; dans le parc = im Park; en retard = verspätet. Je/Nora gehört im zweiten und vierten Satz zur Gruppe.", "sample": "Je suis à Paris.\nNous sommes ensemble.\nElles sont dans le parc.\nOn est en retard.", "criteria": ["Nora spricht im ersten Satz über sich: je suis.", "Die eigene Gruppe steht im zweiten Satz mit nous sommes.", "Die zwei Mädchen, über die Nora spricht, stehen mit elles sont.", "Bei on bleibt est, auch wenn die eigene Gruppe gemeint ist."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "id": "m4-l6-t"}, "check": [{"type": "slots", "prompt": "Nora spricht direkt zu genau einem vertrauten Freund Samir.", "slots": [{"label": "Pronomen", "options": ["il", "tu", "vous"], "answer": 1, "feedback": "Vertraute direkte Anrede einer einzelnen Person: du."}, {"label": "Verb", "options": ["es", "est", "sont"], "answer": 0, "feedback": "Prüfe die geschriebene Form des Paares mit tu."}], "why": "Tu es: vertraute Einzelanrede.", "support": "gemeint: Du bist in Paris.", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-l6-c1"}, {"type": "choice", "prompt": "Welche letzte Kontrolle ist besonders hilfreich?", "options": ["Nur die Anzahl der sichtbaren Namen zählen.", "Bezug und Gesprächsrolle prüfen, dann jedes Pronomen-Verb-Paar und seine Schreibung.", "Alle Verbformen durch est ersetzen."], "answer": 1, "why": "Dieser Kontrollweg berücksichtigt auch on und höfliches vous.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-l6-c2"}], "card": {"rule": "Bezug und Rolle → Pronomen → Verbform → verständlicher ganzer Satz.", "example": "Lina et Inès → elles → sont. Eigene Gruppe mit on → est.", "trap": "Nicht jede falsche Verbindung verlangt ein neues Pronomen. Prüfe erst den Bezug und dann die Verbform."}, "workshop": true}], "exam": {"id": "m4-exam", "label": "Modulprüfung M4", "title": "Wer ist gemeint – und welche Form passt?", "minutes": "25–30", "intro": "Zwölf neue Aufgaben. Elf werden automatisch geprüft. Deinen freien Text vergleichst du separat anhand von vier Kriterien. Wortbedeutungen sind bereitgestellt.", "questions": [{"type": "choice", "prompt": "Was ist das ganze Subjekt in „Les garçons sont dans le parc“?", "options": ["Les garçons", "dans le parc", "sont"], "answer": 0, "why": "Les garçons benennt die Gruppe, über die etwas gesagt wird.", "support": "les garçons = die Jungen; dans le parc = im Park", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-e1", "lesson": "m4-l1"}, {"type": "slots", "prompt": "Nora spricht über la tour, einen einzelnen Turm.", "slots": [{"label": "Pronomen", "options": ["il", "elle", "elles"], "answer": 1, "feedback": "Tour ist français féminin und Singular."}, {"label": "Verb", "options": ["sont", "est", "sommes"], "answer": 1, "feedback": "Zur einzelnen als elle bezeichneten Sache gehört est."}], "why": "La tour → elle est.", "support": "tour = Turm · féminin · Singular; à Paris = in Paris", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-e2", "lesson": "m4-l2"}, {"type": "short", "prompt": "Ergänze nur être: Tu ___ dans la classe.", "answers": ["es"], "why": "Tu es, ohne t.", "support": "dans la classe = in der Klasse", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-e3", "lesson": "m4-l3"}, {"type": "short", "prompt": "Ergänze: Je ___ à Paris.", "answers": ["suis"], "why": "Zu je gehört suis.", "support": "à Paris = in Paris", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-e4", "lesson": "m4-l3"}, {"type": "choice", "prompt": "Samir spricht über sich und zwei andere Kinder. Welches Paar meint seine Gruppe?", "options": ["nous sommes", "ils sont", "vous êtes"], "answer": 0, "why": "Der Sprecher gehört selbst zur Gruppe: nous sommes.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-e5", "lesson": "m4-l4"}, {"type": "choice", "prompt": "Nora spricht über Lina (Mädchen) und Amir (Junge), nicht zu ihnen.", "options": ["elles sont", "ils sont", "vous êtes"], "answer": 1, "why": "Für die angegebene gemischte Gruppe steht hier ils sont.", "support": "", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-e6", "lesson": "m4-l4"}, {"type": "short", "prompt": "On meint hier wir. Ergänze: On ___ ensemble.", "answers": ["est"], "why": "On verlangt grammatisch die dritte Person Singular.", "support": "ensemble = zusammen", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-e7", "lesson": "m4-l5"}, {"type": "slots", "prompt": "Du sprichst genau eine erwachsene fremde Person höflich an.", "slots": [{"label": "Pronomen", "options": ["elle", "tu", "vous"], "answer": 2, "feedback": "Gefordert ist höfliche direkte Anrede."}, {"label": "Verb", "options": ["est", "êtes", "es"], "answer": 1, "feedback": "Höfliches vous verlangt êtes."}], "why": "Vous êtes, auch für die eine höflich angesprochene Person.", "support": "gemeint: Sie sind in Paris.", "hints": ["Erst den Bezug und die Gesprächsrolle prüfen, dann die Form.", "Löse die Felder einzeln und lies anschließend die ganze Verbindung."], "id": "m4-e8", "lesson": "m4-l5"}, {"type": "short", "prompt": "Über zwei Mädchen wird gesprochen: Elles ___ dans le quartier.", "answers": ["sont"], "why": "Zu elles gehört sont.", "support": "dans le quartier = im Viertel", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-e9", "lesson": "m4-l4"}, {"type": "short", "prompt": "Repariere nur das Verb: Vous ___ ensemble.", "answers": ["êtes"], "why": "Vous êtes: êtes mit accent circonflexe.", "support": "vous = ihr; ensemble = zusammen", "hints": ["Wer ist das Subjekt? Welche Form gehört genau dazu?", "Prüfe die Form an der Tabelle oder am ausgearbeiteten Beispiel."], "mistakes": [], "id": "m4-e10", "lesson": "m4-l5"}, {"type": "choice", "prompt": "Welcher Satz ersetzt nur das Subjekt in „Lina est avec Samir“ richtig?", "options": ["Ils sont avec Samir.", "Elle est avec Samir.", "Nous sommes avec Samir."], "answer": 1, "why": "Das Subjekt bleibt Lina, ein Mädchen. Avec Samir ist die zusätzliche Begleitung.", "support": "Lina = Mädchen; est avec Samir = ist mit Samir zusammen", "hints": ["Kläre zuerst die Gesprächsrolle und die gesuchte Information.", "Lies das passende Muster im Erklärungsteil noch einmal."], "id": "m4-e11", "lesson": "m4-l6"}, {"type": "open", "prompt": "Du spielst Amir. Schreibe vier Sätze: Du bist in Paris. Du und Nora seid im Park. Zwei andere Mädchen sind zusammen (verwende elles). Eure eigene Gruppe ist verspätet (verwende on).", "support": "à Paris = in Paris; dans le parc = im Park; ensemble = zusammen; en retard = verspätet.", "sample": "Je suis à Paris.\nNous sommes dans le parc.\nElles sont ensemble.\nOn est en retard.", "criteria": ["Ich-Rolle mit je suis.", "Eigene Gruppe mit nous sommes.", "Die andere Mädchengruppe mit elles sont.", "On mit est, obwohl die eigene Gruppe gemeint ist."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "id": "m4-e12", "lesson": "m4-l6"}]}, "forms": {"je": "suis", "tu": "es", "il": "est", "elle": "est", "on": "est", "nous": "sommes", "vous": "êtes", "ils": "sont", "elles": "sont"}, "cases": [{"id": "ich", "label": "Ich spreche über mich", "context": "Die sprechende Person ist selbst gemeint.", "pronoun": "je", "count": 1}, {"id": "du", "label": "Eine vertraute Person ansprechen", "context": "Nora spricht direkt zu genau einem vertrauten Freund.", "pronoun": "tu", "count": 1}, {"id": "junge", "label": "Über einen Jungen sprechen", "context": "Nora spricht über Samir, laut Rolle einen einzelnen Jungen.", "pronoun": "il", "count": 1}, {"id": "maedchen", "label": "Über ein Mädchen sprechen", "context": "Samir spricht über Nora, laut Rolle ein einzelnes Mädchen.", "pronoun": "elle", "count": 1}, {"id": "on", "label": "Unsere Gruppe mit on", "context": "On ist vorgegeben und meint hier wir. Grammatisch bleibt on dritte Person Singular.", "pronoun": "on", "count": 2}, {"id": "wir", "label": "Über uns selbst sprechen", "context": "Samir spricht über sich und Nora. Der Sprecher gehört dazu.", "pronoun": "nous", "count": 2}, {"id": "ihr", "label": "Eine Gruppe ansprechen", "context": "Nora spricht direkt zu zwei anderen Kindern: ihr.", "pronoun": "vous", "count": 2}, {"id": "hoeflich", "label": "Eine Person höflich ansprechen", "context": "Samir spricht eine einzelne Lehrerin höflich mit Sie an.", "pronoun": "vous", "count": 1}, {"id": "jungen", "label": "Über zwei Jungen sprechen", "context": "Nora spricht über zwei andere Jungen.", "pronoun": "ils", "count": 2}, {"id": "gemischt", "label": "Über eine gemischte Gruppe sprechen", "context": "Nora spricht über Lina (Mädchen) und Samir (Junge). Nora gehört nicht dazu.", "pronoun": "ils", "count": 2}, {"id": "maedchenplural", "label": "Über zwei Mädchen sprechen", "context": "Samir spricht über Nora und Inès, laut Rollenkarte zwei Mädchen.", "pronoun": "elles", "count": 2}, {"id": "museum", "label": "Über das Museum sprechen", "context": "Le musée = das Museum; masculin und Singular. Entscheidend ist das französische Genus.", "pronoun": "il", "count": 1}, {"id": "turm", "label": "Über den Turm sprechen", "context": "La tour = der Turm; féminin und Singular. Entscheidend ist das französische Genus.", "pronoun": "elle", "count": 1}]};const D=globalThis.FRENCH_COURSE;D.lessons.push(...data.lessons);D.exams.m4=data.exam;D.etreForms=data.forms;D.pronounCases=data.cases;})();
